async function seedAccounts(): Promise<Map<string, string>> {
  const passwordHash = await hashPassword(DEMO_PASSWORD);
  const supplierIds = new Map<string, string>();

  await prisma.user.upsert({
    where: { email: 'admin@demo.3dsfera.local' },
    update: { role: 'ADMIN', passwordHash },
    create: { email: 'admin@demo.3dsfera.local', passwordHash, role: 'ADMIN', locale: 'ru' },
  });

  await prisma.user.upsert({
    where: { email: 'buyer@demo.3dsfera.local' },
    update: { passwordHash },
    create: { email: 'buyer@demo.3dsfera.local', passwordHash, role: 'BUYER', locale: 'ru' },
  });

  let slot = 1;
  for (const entry of suppliers) {
    const user = await prisma.user.upsert({
      where: { email: entry.email },
      update: { passwordHash, role: 'SUPPLIER' },
      create: { email: entry.email, passwordHash, role: 'SUPPLIER', locale: 'ru' },
    });

    const supplier = await prisma.supplier.upsert({
      where: { userId: user.id },
      update: {
        companyName: entry.companyName,
        legalName: entry.legalName,
        taxId: entry.taxId,
        status: entry.status,
      },
      create: {
        userId: user.id,
        companyName: entry.companyName,
        legalName: entry.legalName,
        taxId: entry.taxId,
        contactEmail: entry.email,
        status: entry.status,
      },
    });

    supplierIds.set(entry.key, supplier.id);

    if (entry.pavilionTitle) {
      await prisma.pavilion.upsert({
        where: { slot },
        update: { supplierId: supplier.id, title: entry.pavilionTitle },
        create: {
          supplierId: supplier.id,
          slot,
          title: entry.pavilionTitle,
          theme: slot % 2 === 0 ? 'DEEP_BLUE' : 'GRAPHITE',
          status: 'PUBLISHED',
          worldPosition: { x: (slot - 1) * 26, y: 0, z: 0, rotationY: 0 },
        },
      });
      slot += 1;
    }
  }

  return supplierIds;
}

async function seedProduct(supplierId: string, seed: ProductSeed): Promise<void> {
  const pavilion = await prisma.pavilion.findFirst({
    where: { supplierId },
    select: { id: true },
  });

  const product = await prisma.product.upsert({
    where: { slug: seed.slug },
    update: {
      title: seed.title,
      description: seed.description,
      category: seed.category,
      priceCents: seed.priceCents,
      stock: seed.stock,
      weightGrams: seed.weightGrams,
      lengthMm: seed.lengthMm,
      widthMm: seed.widthMm,
      heightMm: seed.heightMm,
      status: seed.status,
      pavilionId: pavilion?.id ?? null,
    },
    create: {
      supplierId,
      pavilionId: pavilion?.id ?? null,
      slug: seed.slug,
      title: seed.title,
      description: seed.description,
      category: seed.category,
      priceCents: seed.priceCents,
      currency: 'RUB',
      stock: seed.stock,
      weightGrams: seed.weightGrams,
      lengthMm: seed.lengthMm,
      widthMm: seed.widthMm,
      heightMm: seed.heightMm,
      status: seed.status,
      submittedAt: new Date(),
      ...(seed.status === 'PUBLISHED' ? { publishedAt: new Date() } : {}),
      // Plausible traffic, so the statistics screen is not a wall of zeroes.
      viewCount: 40 + Math.floor(Math.random() * 400),
      orderCount: Math.floor(Math.random() * 12),
    },
    select: { id: true },
  });

  if (REPROCESS) {
    await prisma.productAsset.deleteMany({ where: { productId: product.id } });
    await prisma.modelJob.deleteMany({ where: { productId: product.id } });
  }

  const alreadyProcessed = await prisma.productAsset.findFirst({
    where: { productId: product.id, kind: 'GLB_OPTIMIZED' },
    select: { id: true },
  });

  if (!alreadyProcessed) {
    const bytes = new Uint8Array(readFileSync(path.join(ASSET_DIR, seed.file)));
    const { jobId } = await attachModel(prisma, product.id, bytes, { enqueue: false });
    await runModelJob(jobId);
  }

  await prisma.productInteraction.deleteMany({ where: { productId: product.id } });
  await prisma.productInteraction.createMany({
    data: seed.interactions.map((interaction, index) => ({
      productId: product.id,
      type: interaction.type,
      clipName: interaction.clipName ?? null,
      label: interaction.label,
      labelEn: interaction.labelEn,
      order: index,
      loop: interaction.loop ?? false,
    })),
  });
}

async function main(): Promise<void> {
  const supplierIds = await seedAccounts();

  for (const seed of products) {
    const supplierId = supplierIds.get(seed.supplierKey);
    if (!supplierId) throw new Error(`Unknown supplier key "${seed.supplierKey}"`);

    process.stdout.write(`  ${seed.title} … `);
    await seedProduct(supplierId, seed);
    console.log('ok');
  }

  const [pavilions, published, pending, assets] = await Promise.all([
    prisma.pavilion.count(),
    prisma.product.count({ where: { status: 'PUBLISHED' } }),
    prisma.product.count({ where: { status: 'PENDING' } }),
    prisma.productAsset.count(),
  ]);

  console.log('\nseed complete');
  console.log(`  admin:     admin@demo.3dsfera.local / ${DEMO_PASSWORD}`);
  console.log(`  buyer:     buyer@demo.3dsfera.local / ${DEMO_PASSWORD}`);
  for (const entry of suppliers) {
    console.log(`  supplier:  ${entry.email} / ${DEMO_PASSWORD}  (${entry.status})`);
  }
  console.log(`  pavilions: ${pavilions}, published: ${published}, pending: ${pending}`);
  console.log(`  assets:    ${assets} objects in storage`);
}

main()
  .catch((error: unknown) => {
    console.error('seed failed:', error);
    process.exitCode = 1;
  })
  .finally(() => {
    void prisma.$disconnect();
  });
